"""new male characters: remarks, events, reactions, laughs (224 clips). Written by the voice director (content), source AssetGen/audio/script/wave_*.txt -> voice_script.json; voice = char_id (VOIX_ARCHITECTURE.md principle 2). Never edit: new content goes to a new batch."""
ITEMS = [
    {'cat': 'remark', 'text': 'Quarante ans de service, et jamais un bal sans incident.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Le sommelier a encore goûté la cave. Toute la cave.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Monsieur a demandé que l'on ne dérange pas le fantôme du grenier.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Les invités sont priés de ne pas nourrir le perroquet.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le lustre a été dépoussiéré ce matin. Il serait dommage qu'il tombe ce soir.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai rangé l'argenterie. Je la recompterai à l'aube.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Il pleut. Comme prévu. Comme toujours.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le maître de maison m'a confié un secret. Je l'emporterai dans la tombe. Ou dans la cave.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La porte du bureau doit rester fermée. Elle ne l'est pas. Je soupire.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Un majordome ne court jamais. Il arrive simplement avant tout le monde.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Les traces de boue dans le hall. Évidemment. Évidemment.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "On m'a demandé si la maison était hantée. J'ai répondu que la maison était occupée.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Le gâteau sera servi à minuit. Les survivants apprécieront.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Je ne juge personne. J'observe, puis je juge en silence.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Encore un verre brisé. Le treizième. Monsieur ne sera pas surpris.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': "Les seaux sont dans l'office ! L'office, voyons !", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_barnabe_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Ne bougez plus, je connais chaque meuble par cœur.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_barnabe_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': "Des malfaiteurs. Je les avais pourtant priés de s'essuyer les pieds.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_barnabe_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': "Cet individu n'est pas sur la liste des invités.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_barnabe_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': "Cet automate n'a pas été annoncé.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_barnabe_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est éteint. Il faudra repeindre le salon. Encore.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_barnabe_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': "La lumière revient. Que personne n'emporte l'argenterie.", 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_barnabe_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Monsieur avait fait accorder ce piano. Hier.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Je vous prie de cesser. Le piano aussi vous en prie.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Le Steinway de Madame. Mon Dieu.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': 'Hm. Je vais ouvrir une fenêtre. Ou toutes.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_barnabe_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Hm.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_barnabe_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Hm hm.', 'voice': 'char_barnabe', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_barnabe_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': 'Ce manoir est charmant. On pourrait le ranger dans un coin de mon palais.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "En Europe, on m'appelle exotique. Chez moi, c'est vous qui l'êtes.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le champagne est un peu tiède. Le thé de chez moi l'est moins.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai apporté une émeraude pour Lady Ashcombe. Elle l'a trouvée petite.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'La tempête gronde comme un tigre qui a faim.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Les Anglais m'ont appris le cricket. Je leur ai appris à perdre.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Un prince ne se perd jamais. Il découvre de nouvelles ailes du château.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ma mère voudrait que je me marie. Ce soir, je me contenterai d'une valse.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Les Européens dansent comme s'ils avaient peur du parquet.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ce turban pèse trois kilos. La couronne en pesait dix.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "On me demande si j'ai des éléphants. Seulement quarante.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le colonel m'a raconté Verdun. Je lui ai raconté la chasse au tigre. Nous sommes quittes.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'La lune est cachée. Elle aussi porte un masque, ce soir.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'aime ces fêtes : tout le monde y joue un rôle, et personne ne connaît le texte.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Mon astrologue m'avait prédit une nuit agitée. Il faudra l'augmenter.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'Le feu se répand ! Faites une chaîne, comme au palais !', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_rajan_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Dans le noir, tout le monde devient prince. Ou voleur.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_rajan_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': "Des bandits ? Qu'ils prennent mes bagues, pas mes amis.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_rajan_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': 'Cet homme a perdu la raison. Éloignez-vous de lui.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_rajan_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': 'Une machine de guerre ? Quelle étrange hospitalité.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_rajan_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est vaincu. Les tapis, moins.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_rajan_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': 'La lumière revient. Comptons-nous, mes amis.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_rajan_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Quel courage, ce pianiste. Et quel bruit.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Chez moi, on aurait offert un sitar à ce musicien. Pour qu'il change d'instrument.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Ce piano souffre. Je l'entends prier.", 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': 'Ah. Une offrande, sans doute. Pas aux bons dieux.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_rajan_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha ha.', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_rajan_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Ho ho !', 'voice': 'char_rajan', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_rajan_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': "Ce piano n'a pas vu un accordeur depuis la guerre.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Les riches dansent la valse comme s'ils payaient chaque pas.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Mon batteur a le mal de mer. Sur la terre ferme.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Un, deux, un deux trois quatre... et ça repart !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "À New York, on jouait jusqu'à six heures du matin. Ici, ils dorment à minuit.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ce manoir a une acoustique de cathédrale. Parfait pour la trompette.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le colonel m'a dit que le jazz, c'était le diable. Le diable a bon goût.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai joué à Harlem, à Paris, et maintenant sur une île. Ma carrière prend l'eau.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La tempête, c'est juste une grosse caisse qui s'énerve.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Tu sens ça ? C'est le swing. Ou le cigare du voisin.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Odette chante comme un ange. Un ange qui fume un peu.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Mon contrebassiste a perdu son archet. Il joue avec une fourchette.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le champagne, c'est bien. Mais le bourbon, ça, c'est du jazz.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La nuit est jeune, et l'orchestre aussi. Enfin, sauf le pianiste.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Je compose un morceau sur cette soirée. Ça s'appellera « Le Blues du Naufragé ».", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'La fumée ! Mes partitions vont cramer !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_sonny_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Dans le noir, je joue de mémoire, pas de problème !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_sonny_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': "Des gangsters ? J'en ai connu à Chicago, ça finit mal.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_sonny_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': 'Ce gars a perdu la mesure, éloignez-vous !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_sonny_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': "Un robot ! Il a pas l'air de swinguer, celui-là.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_sonny_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est éteint. On a perdu une trompette, pas le moral.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_sonny_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': 'Ah, la lumière ! Maestro, on reprend où on en était.', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_sonny_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Hé, doucement avec mon piano, mon pote !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "C'est du free jazz, ça ? Très free. Trop free.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Celui-là, il joue avec ses coudes, c'est sûr.", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': "Ha ! Quelqu'un a joué du trombone !", 'voice': 'char_sonny', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_sonny_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha ha ha !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_sonny_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Hé hé hé !', 'voice': 'char_sonny', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_sonny_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': "Ce manoir est construit sur des ruines romaines. Ou sur une cave. J'hésite.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Les Égyptiens auraient adoré cette tempête. Ils y auraient vu un présage.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai perdu mon chapeau en 1922. Dans un sarcophage. Je n'ai jamais osé le récupérer.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ce vase est une copie. Je le sais, j'ai l'original. Enfin, quelque part.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Où en étais-je ? Ah oui, la malédiction. Elle n'existe pas. Probablement.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le comte Vasilescu m'intéresse beaucoup. Scientifiquement.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Les momies étaient emmaillotées comme ce colonel dans son uniforme.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Je me suis assis sur un petit four. Il était très ancien, lui aussi.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Quand j'étais jeune, j'ai dansé avec une princesse nubienne. Ou avec un chameau. Il faisait nuit.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ce champagne a un goût de sable. Ah non, c'est ma moustache.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le grenier de ce manoir regorge de trésors. J'y monterai à minuit.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La science explique tout. Sauf les invités d'Ashcombe.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ramsès Deux a vécu quatre-vingt-dix ans. Sans champagne. Le pauvre.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Hi hi... pardon, je pensais à une inscription très drôle de Saqqarah.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai écrit douze livres. Ma femme en a lu un. Le plus court.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'Les livres de la bibliothèque ! Sauvez au moins les livres !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_ambroise_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Restez calmes ! Les Égyptiens vivaient très bien à la bougie !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_ambroise_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': 'Des pilleurs ! Ce sont toujours des pilleurs !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_ambroise_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': 'Cet homme est possédé ! Ou alors très, très énervé !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_ambroise_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': "Un automate ! Héron d'Alexandrie en avait fait un. Moins méchant.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_ambroise_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': "Le feu est éteint. Les cendres sont intéressantes, d'ailleurs.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_ambroise_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': 'La lumière ! Ah, mes lunettes étaient sur ma tête.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_ambroise_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Ce son me rappelle un sarcophage qu'on ouvre.", 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Fascinant. On dirait un rituel funéraire.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Les pharaons faisaient fouetter les mauvais musiciens. Je dis ça...', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': 'Oh ! Les gaz des marais. Ou le pâté de lièvre.', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_ambroise_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Hi hi hi...', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_ambroise_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Hé hé, hé hé !', 'voice': 'char_ambroise', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_ambroise_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': "Mon patron m'a dit d'attendre ici. Ça fait trois heures.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Il y a une Rolls dans le garage. J'ose même pas la regarder.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le bateau est reparti sans nous. J'aurais pu le réparer, moi, le moteur.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Pardon. Pardon. Oh, pardon. Ces couloirs sont trop étroits.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Les riches mangent des petits trucs sur des petits pains. J'ai encore faim.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Si ma mère me voyait en livrée, ici, elle pleurerait de fierté.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai jamais vu autant de cristal. J'ai peur d'éternuer.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'La pluie va rouiller les chromes. Ça me fend le cœur.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Une dame m'a demandé de danser. J'ai dit non, j'avais trop peur pour ses pieds.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le majordome me regarde comme si j'étais une tache sur le tapis.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Moi, une soirée, c'est un casse-croûte et un bal musette.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ils parlent tous de la Bourse. Moi, je parle de carburateurs. Personne m'écoute.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Pardon, monsieur. Ah non, c'est une statue.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Si quelqu'un a besoin d'une voiture, je suis là. Enfin, pas de voiture, mais je suis là.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai graissé les gonds de la grande porte. Plus personne n'entendra qui sort.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': "Le garage ! Si le feu atteint l'essence, tout saute !", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_lucien_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': "J'ai une lampe torche, suivez-moi ! Enfin, si je la trouve.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_lucien_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': "Des bandits ! J'ai laissé les clés sur la voiture, mince !", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_lucien_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': 'Il a de la dynamite ! Comme dans les carrières !', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_lucien_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': 'Un robot ! Je me demande quel moteur il a.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_lucien_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': "C'est éteint. J'ai sauvé un extincteur. Enfin, il était vide.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_lucien_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': "La lumière ! Ça devait être un fusible. Je l'aurais réparé, moi.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_lucien_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Ça cogne comme un moteur mal réglé.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Pardon, mais ce piano a besoin d'une vidange.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Même mon klaxon joue mieux que ça.', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': "Oh ! Pardon. Non, c'est pas moi. Je crois pas.", 'voice': 'char_lucien', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_lucien_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Hé hé...', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_lucien_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha, pardon !', 'voice': 'char_lucien', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_lucien_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': "Ces gants ? Je les enlève jamais. Les empreintes, c'est personnel.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le champagne français, c'est bien. Mais chez nous, on le fait dans la baignoire.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Quelqu'un ici me doit cinq mille dollars. Il porte une queue-de-pie.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Je suis dans les affaires. Les affaires des autres, surtout.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Belle maison. Elle serait encore plus belle avec un casino dedans.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'La police, ici ? Ces types en imperméable ? Je les connais pas. Pas encore.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ma mère disait : Tony, sois gentil. Alors je suis gentil. Avec le sourire.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Cette tempête, c'est parfait. Personne entre, personne sort.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai pas de revolver ce soir. J'ai mieux : des amis.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Un homme poli vit plus longtemps. Enfin, en général.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ce majordome me regarde de travers. Il faudrait qu'on parle, lui et moi.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Moi, je fais pas de menaces. Je fais des prévisions.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le baccara ici, c'est truqué. Je le sais, c'est moi qui l'aurais truqué.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le comte me plaît. Il a l'air de quelqu'un qui enterre bien ses problèmes.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "À Chicago, on m'appelle le gentleman. Les autres sont plus là pour dire autre chose.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': "Le feu ! Quelqu'un a pas payé son assurance !", 'voice': 'char_tony', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tony_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Dans le noir, je reconnais mes amis à la voix. Et mes ennemis aussi.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_tony_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': 'Des amateurs ! Qui leur a donné le droit de travailler ici ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tony_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': 'Ce type est cinglé ! Même chez nous, on fait pas ça !', 'voice': 'char_tony', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tony_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': 'Un robot ? Je veux le même pour mes collecteurs.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tony_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est éteint. Bon. Retour aux affaires.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_tony_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': "La lumière. Tout le monde a encore son portefeuille ? Pour l'instant.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_tony_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Celui qui joue comme ça, il mérite qu'on lui parle des doigts.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Hé, le pianiste ! Tu veux garder tes mains ?', 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Ce piano chante plus faux qu'un indic de la police.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': "Qui a fait ça ? Avoue, et il t'arrivera rien.", 'voice': 'char_tony', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tony_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Heh heh heh.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_tony_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha. Ha.', 'voice': 'char_tony', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_tony_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': 'Au Texas, nos lustres sont plus grands que ça.', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai acheté trois puits de pétrole avant le petit-déjeuner.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ce manoir ? Je pourrais l'acheter. Je vais peut-être l'acheter.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le caviar, c'est des œufs de poisson. Chez moi, on mange le poisson entier.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ha ! Le colonel m'a dit que j'étais bruyant. Je lui ai répondu plus fort.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La pluie ici est toute petite. Au Texas, elle tombe à l'horizontale.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Mon chapeau fait dix gallons. Mon verre, lui, est vide.', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Les Européens boivent dans des dés à coudre !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai un cheval qui s'appelle Napoléon. Il est plus grand que le vrai.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le bal le plus chic de Dallas, c'est chez moi. Avec des vaches.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ma femme voulait voir la France. Moi, je voulais voir la France l'acheter.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ce champagne pétille presque autant que mon pétrole.', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Quelqu'un ici sait faire un barbecue ? Non ? Quel pays !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ha ha ! Cette musique est trop lente. Il faut du violon et des bottes !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le Texas, c'est grand comme la France. En mieux.", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'Ça brûle comme un puits de pétrole ! Reculez !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tex_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Pas de panique ! Au Texas, on a des pannes tous les jours !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_tex_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': "Des bandits ! Ha ! J'ai connu pire à Amarillo !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tex_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': 'Ce gars est fou à lier ! Écartez-vous, vite !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tex_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': "Un robot ! Combien il coûte ? J'en veux deux !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_tex_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est éteint. Mon puits numéro six aurait dû avoir cette chance.', 'voice': 'char_tex', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_tex_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': 'Ah ! La lumière ! Comme au Texas, mais en plus petit.', 'voice': 'char_tex', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_tex_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Ha ! Plus fort, l'ami, plus fort !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Au Texas, on joue du piano avec les bottes !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Ça, c'est de la musique de saloon ! J'adore !", 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': 'Ha ha ha ! Au Texas, on appelle ça une ovation !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_tex_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha ha ha ha !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_tex_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Ho ho ho ho !', 'voice': 'char_tex', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_tex_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': 'Force huit, et ça monte. Le bateau ne reviendra pas avant demain midi.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "En vingt-quatre, j'ai traversé un ouragan avec deux mille passagers. Pas un verre cassé.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ce manoir craque comme une coque en pleine mer.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le baromètre du hall dégringole. Je l'avais dit.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Les Bretons ne craignent pas la tempête. Ils la regardent dans les yeux.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "On m'a proposé du rhum. J'ai accepté. C'est une tradition.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Un capitaine ne dort jamais vraiment. Il écoute le vent.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le phare de l'île s'est éteint. Mauvais signe pour les bateaux.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Les invités tournent en rond comme des passagers perdus sur le pont.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai connu des icebergs plus chaleureux que la duchesse.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La mer rend ce qu'elle prend. Pas toujours le même jour.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ce lustre se balance au rythme de la houle. Fascinant.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "À bord, on aurait déjà fait l'exercice d'évacuation.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le jazz, c'est comme la mer : ça monte, ça descend, et on finit trempé.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai cinquante-huit ans, dont quarante sur l'eau. Le sol me donne le vertige.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': "Coupez l'air, fermez les portes, le feu ne doit pas respirer !", 'voice': 'char_morel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_morel_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': "Personne ne bouge ! Attendez que vos yeux s'habituent !", 'voice': 'char_morel', 'gender': 'm', 'reg': 'startled', 'line_id': 'L_morel_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': 'Des pirates. Ça existe encore, apparemment.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_morel_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': "Cet homme va se faire sauter ! Éloignez-vous, c'est un ordre !", 'voice': 'char_morel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_morel_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': "Une machine armée ? Je n'en ai jamais vu, même sur un cuirassé.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'panic', 'line_id': 'L_morel_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Feu éteint. Bon travail, tout le monde.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_morel_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': "La lumière revient. Faites l'appel, chacun avec son voisin.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'awkward', 'line_id': 'L_morel_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Ça sonne comme une tempête en mer d'Iroise.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "J'ai connu des cornes de brume plus mélodieuses.", 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Ce pianiste joue comme un mousse son premier jour.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': 'Hm. Vent arrière, comme on dit.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'L_morel_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha ha.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_morel_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Ho ho.', 'voice': 'char_morel', 'gender': 'm', 'reg': 'design:laugh', 'line_id': 'L_morel_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
]
